contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint callerPrior) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        uint beforeTimestamp = c.pastBlockTime();
        uint beforeBalance = address(c).balance;
        uint beforeSelf = address(this).balance;

        bool reverted;

        // If this is the first accepted call, beforeTimestamp is zero and
        // the fallback guard passes because block.timestamp is positive.
        if (beforeTimestamp == 0) {
            try c.fallback{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Make the cached timestamp stale so a valid 10-ether call can pass.
            uint stale = callerPrior;
            if (stale >= beforeTimestamp) {
                stale = beforeTimestamp - 1;
            }
            c.fallback{value: amount}();
            require(c.pastBlockTime() == block.timestamp);
            // Only the canonical call made first in each block can be tested here.
            // The remaining behavior is captured by the first-call case.
            reverted = true;
        }

        uint afterTimestamp = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        if (!reverted) {
            uint delta = afterBalance + amount - beforeBalance;
            if (block.number % 15 == 0) {
                assert(delta == 0);
            } else {
                assert(delta == amount);
            }
            assert(afterTimestamp == block.timestamp);
            assert(afterTimestamp > beforeTimestamp || beforeTimestamp == 0);
        }
    }

    receive() external payable {}
}

