        uint afterBalance = address(c).balance;

        assert(afterTimestamp == block.timestamp);
        assert(afterTimestamp > beforeTimestamp);
        if (block.number % 15 == 0) {
            assert(afterBalance == 0);
        } else {
            assert(afterBalance == beforeBalance + amount);
        }
    }
}

