contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 targetPastBlockTime) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);
        require(targetPastBlockTime > block.timestamp);

        // Set up: put the contract into a state where pastBlockTime is a known value.
        // We need to ensure pastBlockTime >= targetPastBlockTime before the deciding call.
        // There is no direct setter; we must perform a successful call with a timestamp > pastBlockTime.
        // However, we cannot control block.timestamp (it is always current time).
        // To set pastBlockTime to a value >= targetPastBlockTime, we need a successful call
        // with a timestamp >= targetPastBlockTime. But block.timestamp is fixed in this transaction.
        // So we require targetPastBlockTime <= block.timestamp for the first call to succeed,
        // then we can read pastBlockTime (which will be block.timestamp) and make a second call.
        //
        // Since block.timestamp is constant during a transaction, the second call will fail
        // because block.timestamp > pastBlockTime is false (equal).
        // Thus we cannot set pastBlockTime to an arbitrary value > block.timestamp.
        // We must work with the current block.timestamp.
        //
        // Alternative setup: we can set pastBlockTime by calling once with 10 ether.
        // But then the deciding call would have the same timestamp and revert.
        // The only way to have a successful call (other than the first) is if
        // the setup doesn't change pastBlockTime (e.g., a failed call).
        // A failed call reverts and does not change state.
        // So if pastBlockTime == block.timestamp, any call will fail.
        //
        // To observe the behavior described, we need a successful call.
        // The fresh c has pastBlockTime = 0. So a call with 10 ether and block.timestamp > 0
        // will succeed if block.timestamp > 0 (always true).
        // But we want to test the general rule: for any call with 10 ether and timestamp > pastBlockTime,
        // the effects are as described. We can drive c by making one successful call.
        // The precondition for success: amount == 10 ether and block.timestamp > c.pastBlockTime().
        // Since block.timestamp is fixed, we just need c.pastBlockTime() < block.timestamp.
        // Since c is fresh, pastBlockTime = 0, so condition holds.
        // So we can do a single call.

        // Read before state
        uint256 beforePastBlockTime = c.pastBlockTime();
        uint256 beforeBalance = address(c).balance;
        uint256 thisBeforeBalance = address(this).balance;

        // Deciding call: send exactly 10 ether to fallback
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After state reads
        uint256 afterPastBlockTime = c.pastBlockTime();
        uint256 afterBalance = address(c).balance;
        uint256 thisAfterBalance = address(this).balance;

        // General rule: call succeeds iff block.timestamp > beforePastBlockTime.
        // Since amount == 10 ether and preconditions hold, it must succeed.
        // If successful, pastBlockTime becomes block.timestamp, and balance changes only if block.number % 15 == 0.
        // If not successful, state unchanged.

        // We assert the rule for the observed execution:
        if (!reverted) {
            // Must have succeeded, so block.timestamp > beforePastBlockTime
            assert(block.timestamp > beforePastBlockTime);
            assert(afterPastBlockTime == block.timestamp);
            if (block.number % 15 == 0) {
                // All balance forwarded to msg.sender (this contract)
                assert(afterBalance == 0);
                // This contract receives the balance (minus gas, but balance change is exact in terms of c)
                // Actually c.transfer sends entire balance to msg.sender, so this contract's balance increases by beforeBalance + amount.
                // But this contract's balance also decreased by amount sent. Net: thisAfterBalance == thisBeforeBalance + beforeBalance.
                // However, we cannot assert exact equality due to possible other balance changes? We only sent amount.
                // So we can assert thisAfterBalance == thisBeforeBalance - amount + beforeBalance + amount? Wait, c's balance becomes 0, and this receives beforeBalance + amount? Not exactly: c had beforeBalance, receives amount, then sends entire balance (beforeBalance + amount) to this.
                // So thisAfterBalance = thisBeforeBalance - amount + (beforeBalance + amount) = thisBeforeBalance + beforeBalance.
                assert(thisAfterBalance == thisBeforeBalance + beforeBalance);
            } else {
                // No transfer, so c's balance increases by amount
                assert(afterBalance == beforeBalance + amount);
                assert(thisAfterBalance == thisBeforeBalance - amount);
            }
        } else {
            // Reverted: state must be unchanged
            assert(afterPastBlockTime == beforePastBlockTime);
            assert(afterBalance == beforeBalance);
            assert(thisAfterBalance == thisBeforeBalance);
            // Also, revert must be due to timestamp not greater
            assert(block.timestamp <= beforePastBlockTime);
        }
    }

    receive() external payable {}
}

