contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        // Ensure we can send exactly 10 ether.
        require(address(this).balance >= 10 ether);

        // First, establish a baseline pastBlockTime via a fallback call.
        // Use a benign amount to avoid requiring the caller to have extra ether.
        bool setupOk;
        try c.call{value: 10 ether}("") {
            setupOk = true;
        } catch {
            setupOk = false;
        }
        // If the setup call fails, the contract state may not have a usable
        // pastBlockTime; skip further checks by requiring setup success.
        require(setupOk);

        uint256 beforeTime = c.pastBlockTime();
        uint256 beforeBalance = address(c).balance;

        // Deciding call: send exactly 10 ether to the fallback.
        bool reverted;
        try c.call{value: 10 ether}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTime = c.pastBlockTime();
        uint256 afterBalance = address(c).balance;

        // General rule: on success:
        //   - timestamp increases (strictly, because require(block.timestamp > pastBlockTime))
        //   - pastBlockTime becomes the current block.timestamp (afterTime == block.timestamp)
        //   - if block.number % 15 != 0, balance increases by exactly 10 ether
        //   - if block.number % 15 == 0, entire balance is sent to caller: afterBalance == 0
        // On failure (revert due to timestamp not strictly greater):
        //   - pastBlockTime and balance remain unchanged.
        // We can only check the success path if reverted is false.
        if (!reverted) {
            // The require ensures the new timestamp is strictly greater than beforeTime.
            assert(
                afterTime > beforeTime &&
                afterTime == block.timestamp &&
                (
                    (block.number % 15 != 0 && afterBalance == beforeBalance + 10 ether) ||
                    (block.number % 15 == 0 && afterBalance == 0)
                )
            );
        } else {
            // On revert, the state must be unchanged.
            assert(afterTime == beforeTime && afterBalance == beforeBalance);
        }
    }

    receive() external payable {}
}

