contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint targetBlockNumber) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        // Ensure the fallback can pass its timestamp check.
        uint setupTimestamp = c.pastBlockTime();
        uint setupBalance = address(c).balance;

        // Make the deciding call. The fallback uses the actual block.number, so we compute
        // the same expected branch for the assertion below.
        bool reverted;
        try c.call{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint postTimestamp = c.pastBlockTime();
        uint postBalance = address(c).balance;

        if (reverted) {
            // A reverting fallback must leave c's observable state unchanged.
            assert(postTimestamp == setupTimestamp && postBalance == setupBalance);
        } else {
            // A successful fallback updates pastBlockTime and drains c's balance only
            // when the execution block number is divisible by 15.
            bool drained = block.number % 15 == 0;
            if (drained) {
                assert(postTimestamp == block.timestamp && postBalance == 0);
            } else {
                assert(postTimestamp == block.timestamp && postBalance == setupBalance + amount);
            }
